def classifyMstEdges(n, edges):
    E = len(edges)
    order = sorted(range(E), key=lambda i: edges[i][2])
    INF = float('inf')

    def kruskal(skip, force):
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        total = 0
        used = 0
        if force >= 0:
            a, b, w = edges[force]
            parent[find(a)] = find(b)
            total += w
            used += 1
        for i in order:
            if i == skip or i == force:
                continue
            a, b, w = edges[i]
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
                total += w
                used += 1
        return total if used == n - 1 else INF

    best = kruskal(-1, -1)
    res = []
    for i in range(E):
        if kruskal(i, -1) > best:
            res.append(2)
        elif kruskal(-1, i) == best:
            res.append(1)
        else:
            res.append(0)
    return res
